        max_rest = current_rest

    # Since days repeat endlessly, we can connect the end of the day with the beginning
    # The maximal rest in the infinite loop is either the max segment within a single day
    # or the combination of the suffix 1s of the day and the prefix 1s of the next day.

    # Find suffix 1s count
    suffix_ones = 0
    for i in range(n - 1, -1, -1):
